  `step_name` varchar(255) DEFAULT NULL,
  `script_id` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FKqt39v6vqsxi30u14p60kv8yk4` (`script_id`),
  CONSTRAINT `FKqt39v6vqsxi30u14p60kv8yk4` FOREIGN KEY (`script_id`) REFERENCES `script` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
